window.addEventListener('error',()=>{const a=document.getElementById('app');if(a&&!a.innerHTML.trim())a.innerHTML='<div class="wrap"><div class="panel"><h2>QuiverCRM</h2><p>There was a problem loading the app. Please refresh.</p></div></div>';});
const STAGES=['new','contacted','processing','awaiting_payment','fulfilled','won','lost','cancelled'];
const state={loading:true,hasAdmin:false,me:null,vendor:null,vendors:[],view:'auth',tab:'orders',orders:[],customers:[],contacts:[],selectedContactId:null,tasks:[],users:[],report:null,activity:[],authError:'',toast:null,dataWarning:'',serverError:'',creatingTask:false,creatingUser:false,reportOpen:false,viewingStage:null,custQ:'',custSource:'',custFrom:'',custTo:'',custSort:'recent',pipeQ:'',pipeAssignee:'',pipeSource:'',pipeFrom:'',pipeTo:'',pipeShowArchived:false,creatingVendor:false,authMode:'login',subscription:null,resetRequests:[],contactQ:'',contactStatus:'',contactAssignee:'',contactSource:'',contactPriority:'',contactFollow:'',creatingContact:false};
async function api(path,options={}){
  const {timeoutMs=10000, ...fetchOptions}=options;
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),timeoutMs);
  try{
    const headers={'Content-Type':'application/json',...(fetchOptions.headers||{})};
    const request={...fetchOptions,credentials:'include',headers,signal:controller.signal};
    if(request.body!==undefined && request.body!==null && typeof request.body!=='string')request.body=JSON.stringify(request.body);
    const res=await fetch(path,request);
    let data=null;try{data=await res.json()}catch{}
    if(!res.ok){const e=new Error(data?.error||`Request failed (${res.status})`);e.status=res.status;throw e}
    return data;
  }catch(e){
    if(e.name==='AbortError'){const x=new Error('The CRM server took too long to respond. Please try again.');x.status=408;throw x}
    if(e instanceof TypeError){const x=new Error('Could not reach the CRM server. Please check the connection and try again.');x.status=0;throw x}
    throw e;
  }finally{clearTimeout(timer)}
}
function showToast(msg){state.toast=msg;render();setTimeout(()=>{state.toast=null;render()},2500)}
async function init(){
  state.loading=true;state.serverError='';state.authError='';state.dataWarning='';
  render();
  try{
    // Check whether an administrator exists before checking the session. This
    // keeps a logged-out browser on the normal Login screen instead of
    // incorrectly showing the first-time Setup screen.
    try{const s=await api('/api/status',{timeoutMs:5000});state.hasAdmin=!!s.hasAdmin}catch(e){}
    state.me=await api('/api/me',{timeoutMs:8000});
    state.hasAdmin=!!(state.me.role==='admin'||state.me.platformAdmin)||state.hasAdmin;
    state.view='app';
    state.loading=false;
    render();
    // Load workspace data after the shell is visible. A slow endpoint must
    // never leave the whole application stuck on the initial Loading screen.
    loadAppData().catch(e=>{
      state.dataWarning=e.message||'Some CRM data could not be loaded.';
      render();
    });
  }catch(e){
    if(e.status===401){state.me=null;state.view='auth';state.authError='Your session has ended. Please log in again.'}
    else{state.view='error';state.serverError=e.message||'The CRM is temporarily unavailable.'}
    state.loading=false;render();
  }
}
async function retryApp(){if(state.me){state.dataWarning='';render();await loadAppData();render()}else{await init()}}
async function loadAppData(){
  if(!state.me)return;
  const entries=[['orders','/api/orders'],['customers','/api/customers'],['contacts','/api/contacts'],['tasks','/api/tasks']];
  if(!state.me.platformAdmin)entries.push(['vendor','/api/vendor'],['subscription','/api/vendor/subscription']);
  if(state.me.role==='admin')entries.push(['users','/api/admin/users']);
  if(state.me.platformAdmin){entries.push(['vendors','/api/platform/vendors']);entries.push(['resetRequests','/api/platform/password-reset-requests']);}
  const results=await Promise.allSettled(entries.map(([,url])=>api(url,{timeoutMs:10000})));
  const failures=[];
  results.forEach((r,i)=>{
    const [key]=entries[i];
    if(r.status==='fulfilled'){state[key]=r.value;if(key==='contacts'&&!Array.isArray(state[key]))state[key]=Array.isArray(state[key]?.contacts)?state[key].contacts:[];}
    else{
      failures.push(`${key}: ${r.reason?.message||'unavailable'}`);
      if(['orders','customers','contacts','tasks','users','vendors','resetRequests'].includes(key)&&!Array.isArray(state[key]))state[key]=[];
    }
  });
  state.dataWarning=failures.length?`Some CRM data could not be loaded: ${failures.join(' · ')}`:'';
  render();
}

async function handleAuthSubmit(f){const d=new FormData(f),username=(d.get('username')||'').trim(),password=(d.get('password')||'').trim();if(state.authMode==='forgot'){if(!username)return showToast('Enter your username');try{const r=await api('/api/password-reset/request',{method:'POST',body:{username}});state.authError=r.message;state.authMode='login';render()}catch(e){state.authError=e.message;render()}return}if(!username||!password)return showToast('Enter a username and password');state.authError='';try{let result;if(state.authMode==='signup')result=await api('/api/signup',{method:'POST',body:{username,password,name:(d.get('name')||'').trim(),companyName:(d.get('companyName')||'').trim()}});else if(!state.hasAdmin)result=await api('/api/setup',{method:'POST',body:{username,password,setupKey:(d.get('setupKey')||'').trim(),name:(d.get('name')||'').trim(),companyName:(d.get('companyName')||'').trim()}});else result=await api('/api/login',{method:'POST',body:{username,password}});state.me=result.user;state.hasAdmin=true;state.view='app';await loadAppData();render()}catch(e){state.authError=e.message;render()}}
async function logout(){try{await api('/api/logout',{method:'POST'})}catch{}state.me=null;state.view='auth';render()}
