async function setOrderStage(id,stage){try{const o=await api('/api/orders/'+id,{method:'PATCH',body:{pipelineStage:stage}});const i=state.orders.findIndex(x=>x.id===id);state.orders[i]=o;showToast(stage==='won'&&o.receiptNumber?'Sale marked Won — receipt '+o.receiptNumber+' created':'Pipeline updated');render()}catch(e){showToast(e.message)}}
async function ensureReceipt(id){try{const o=await api('/api/orders/'+id+'/receipt',{method:'POST'});const i=state.orders.findIndex(x=>x.id===id);if(i>=0)state.orders[i]=o;return o}catch(e){showToast(e.message);return null}}
function receiptItemsHtml(o){const items=Array.isArray(o.items)?o.items:[];if(!items.length)return '<tr><td colspan="4">Order items</td></tr>';return items.map(i=>`<tr><td>${escapeHtml(i.name||'Unnamed item')}</td><td>${Number(i.qty||0)}</td><td>${money(i.price,o.currency)}</td><td>${money(Number(i.price||0)*Number(i.qty||0),o.currency)}</td></tr>`).join('')}
function receiptHtml(o,vendor){const business=vendor?.name||vendor?.companyName||o.vendorName||o.storeName||'Your Store';const customerPhone=o.phone||'';return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(o.receiptNumber||'Receipt')}</title><style>body{font-family:Arial,sans-serif;color:#1B2030;margin:0;padding:28px;background:#fff}.receipt{max-width:760px;margin:auto;border:1px solid #ddd;padding:32px}.head{text-align:center;border-bottom:2px solid #1B2030;padding-bottom:18px;margin-bottom:20px}.head h1{margin:0 0 6px;font-size:25px}.muted{color:#666;font-size:13px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:20px}.meta div{padding:5px 0}.customer{margin-bottom:20px}.customer strong{display:block;margin-bottom:4px}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{text-align:left;padding:9px 6px;border-bottom:1px solid #ddd}th{font-size:12px;text-transform:uppercase;color:#666}.num{text-align:right}.total{font-size:20px;font-weight:700;text-align:right;border-top:2px solid #1B2030;padding-top:12px}.footer{text-align:center;margin-top:28px;padding-top:18px;border-top:1px solid #ddd;font-size:13px;color:#666}.actions{text-align:center;margin:18px 0}.actions button{padding:9px 15px;border:0;background:#1B2030;color:white;border-radius:4px;cursor:pointer}@media print{body{padding:0}.receipt{border:0;max-width:none;padding:18px}.actions{display:none}}</style></head><body><div class="receipt"><div class="head"><h1>${escapeHtml(business)}</h1><div class="muted">SALES RECEIPT</div></div><div class="meta"><div><strong>Receipt No:</strong> ${escapeHtml(o.receiptNumber||'—')}</div><div><strong>Date:</strong> ${escapeHtml(dt(o.receiptCreatedAt||o.createdAt))}</div><div><strong>Order No:</strong> ${escapeHtml(o.externalId||o.id)}</div><div><strong>Payment:</strong> ${escapeHtml(o.paymentMethod||'Not specified')}</div></div><div class="customer"><strong>Customer</strong><div>${escapeHtml(o.customerName||'—')}</div><div>${escapeHtml(customerPhone||'—')}</div><div>${escapeHtml([o.address,o.town,o.province].filter(Boolean).join(', ')||'—')}</div></div><table><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th class="num">Amount</th></tr></thead><tbody>${receiptItemsHtml(o)}</tbody></table><div class="total">TOTAL: ${money(o.total,o.currency)}</div><div class="muted" style="margin-top:8px">Served by: ${escapeHtml(o.assignedToName||'—')}</div><div class="footer">Thank you for your business!</div><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div></div></body></html>`}
async function viewReceipt(id){const o=await ensureReceipt(id);if(!o)return;const html=receiptHtml(o,state.vendor);const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const w=window.open(url,'_blank');if(!w){URL.revokeObjectURL(url);showToast('Please allow pop-ups to view the receipt');return}setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function printReceipt(id){await viewReceipt(id)}
async function whatsappReceipt(id){const o=await ensureReceipt(id);if(!o)return;const phone=String(o.phone||'').replace(/[^0-9]/g,'');if(!phone){showToast('This customer has no phone number');return}const business=state.vendor?.name||state.vendor?.companyName||o.vendorName||o.storeName||'our business';const text=`Hello ${o.customerName||'there'}, thank you for your purchase from ${business}. Your receipt ${o.receiptNumber} for ${money(o.total,o.currency)} is ready. Thank you for your business!`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}
