async function addCustomerNote(id,f){const d=new FormData(f),text=(d.get('notes')||'').trim();if(!text)return showToast('Write a note first');try{const c=await api('/api/customers/'+id+'/notes',{method:'POST',body:{text}});const i=state.customers.findIndex(x=>x.id===id);state.customers[i]=c;showToast('Note saved');render()}catch(e){showToast(e.message)}}
