function dispositionLabel(s){return String(s||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase())}
function contactSources(){return[...new Set(state.contacts.map(c=>c.source).filter(Boolean))].sort()}
function contactTags(c){return Array.isArray(c.tags)?c.tags:[]}
function filteredContacts(){const q=(state.contactQ||'').trim().toLowerCase(),status=state.contactStatus||'',assignee=state.contactAssignee||'',source=state.contactSource||'',priority=state.contactPriority||'',follow=state.contactFollow||'';let list=state.contacts.filter(c=>{if(q){const hay=[c.name,c.company,c.phone,c.altPhone,c.email,c.town,c.province,c.address,c.source,c.status,c.type,contactTags(c).join(' '),Array.isArray(c.notes)?c.notes.map(n=>n.text).join(' '):''].join(' ').toLowerCase();if(!hay.includes(q))return false}if(status&&c.status!==status)return false;if(assignee&&c.assignedTo!==assignee)return false;if(source&&c.source!==source)return false;if(priority&&c.priority!==priority)return false;if(follow==='due'){if(!c.nextFollowUp||new Date(c.nextFollowUp)>new Date())return false}if(follow==='overdue'){if(!c.nextFollowUp||new Date(c.nextFollowUp)>=new Date())return false}return true});return list.sort((a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt))}
