async function createContact(f){const d=new FormData(f);try{const c=await api('/api/contacts',{method:'POST',body:{name:d.get('name'),company:d.get('company'),phone:d.get('phone'),altPhone:d.get('altPhone'),email:d.get('email'),town:d.get('town'),province:d.get('province'),address:d.get('address'),type:d.get('type'),source:d.get('source'),status:d.get('status'),priority:d.get('priority'),assignedTo:d.get('assignedTo')}});state.contacts.unshift(c);state.selectedContactId=c.id;state.creatingContact=false;showToast('Contact created');render()}catch(e){showToast(e.message)}}
