async function logContactInteraction(id,f){const d=new FormData(f);try{const c=await api('/api/contacts/'+id+'/interactions',{method:'POST',body:{method:d.get('method'),disposition:d.get('disposition'),note:d.get('note'),nextFollowUp:d.get('nextFollowUp')?new Date(d.get('nextFollowUp')).toISOString():null}});const i=state.contacts.findIndex(x=>x.id===id);if(i>=0)state.contacts[i]=c;showToast('Interaction saved');render()}catch(e){showToast(e.message)}}
function csvParse(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(quoted){if(ch==='"'&&next==='"'){cell+='"';i++;}else if(ch==='"')quoted=false;else cell+=ch;}else if(ch==='"'){quoted=true;}else if(ch===','){row.push(cell);cell='';}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell='';}else if(ch==='\r'){}else cell+=ch;}row.push(cell);if(row.some(x=>x!==''))rows.push(row);if(!rows.length)return [];const headers=rows[0].map(h=>String(h).trim().toLowerCase().replace(/[^a-z0-9]+/g,''));const aliases={name:['name','fullname','contactname','customername'],phone:['phone','mobile','mobilenumber','telephone','phonenumber'],altPhone:['altphone','alternativephone','secondaryphone'],email:['email','emailaddress'],company:['company','companyname','organisation','organization'],town:['town','city'],province:['province','state'],address:['address','streetaddress'],type:['type','contacttype'],source:['source','leadsource'],status:['status','contactstatus'],priority:['priority'],tags:['tags','tag'],assignedTo:['assignedto','owner','salesperson','username']};const indexFor=keys=>{for(const k of keys){const i=headers.indexOf(k);if(i>=0)return i}return -1};const idx=Object.fromEntries(Object.entries(aliases).map(([k,v])=>[k,indexFor(v)]));return rows.slice(1).map(r=>{const o={};for(const [k,i] of Object.entries(idx))o[k]=i>=0?String(r[i]||'').trim():'';return o}).filter(r=>Object.values(r).some(Boolean))}
function csvCell(v){const s=String(v??'');return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
async function handleContactsCSV(input){const file=input.files?.[0];if(!file)return;try{const rows=csvParse(await file.text());if(!rows.length)return showToast('The CSV contains no contact rows');const preview=await api('/api/contacts/import/preview',{method:'POST',body:{rows}});const summary=`${preview.newCount} new · ${preview.duplicateCount} duplicates · ${preview.invalidCount} invalid`;const mode=confirm(`CSV preview: ${preview.total} rows\n\n${summary}\n\nOK = import new contacts and skip duplicates.\nCancel = stop import.`);if(!mode)return;const result=await api('/api/contacts/import',{method:'POST',body:{rows,duplicateMode:'skip'}});showToast(`Imported ${result.imported} contacts · skipped ${result.skipped} duplicates`);await loadAppData()}catch(e){showToast(e.message)}finally{input.value=''}}
function downloadContactsCSV(){const cols=['Name','Company','Phone','Alt Phone','Email','Town','Province','Address','Type','Source','Status','Priority','Tags','Assigned To','Last Contacted','Next Follow-up','Contact Attempts'];const rows=state.contacts.map(c=>[c.name,c.company,c.phone,c.altPhone,c.email,c.town,c.province,c.address,c.type,c.source,c.status,c.priority,contactTags(c).join('|'),c.assignedToName,c.lastContactedAt?new Date(c.lastContactedAt).toLocaleString():'',c.nextFollowUp?new Date(c.nextFollowUp).toLocaleString():'',c.contactAttempts||0]);const csv=[cols,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='quivercrm-contacts-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function deleteContact(id){const c=state.contacts.find(x=>x.id===id);if(!c||!confirm(`Delete contact "${c.name}"? Existing orders will remain.`))return;try{await api('/api/contacts/'+id,{method:'DELETE'});state.contacts=state.contacts.filter(x=>x.id!==id);state.selectedContactId=null;showToast('Contact deleted');render()}catch(e){showToast(e.message)}}
function contactOrderMatches(c){return state.orders.filter(o=>(o.contactId&&o.contactId===c.id)||(!o.contactId&&String(o.phone||'').replace(/\D/g,'')===String(c.phone||'').replace(/\D/g,'')))}
function setCustField(field,value){state[field]=value;render()}
function setPipeField(field,value){state[field]=value;render()}
function customerSources(){return[...new Set(state.customers.map(c=>c.source).filter(Boolean))].sort()}
function filteredCustomers(){const q=state.custQ.trim().toLowerCase();const from=state.custFrom?new Date(state.custFrom):null;const to=state.custTo?new Date(state.custTo+'T23:59:59'):null;let list=state.customers.filter(c=>{if(q){const hay=[c.name,c.phone,c.altPhone,c.email,c.address,c.town,c.province,c.source,notesText(c)].join(' ').toLowerCase();if(!hay.includes(q))return false}if(state.custSource&&c.source!==state.custSource)return false;const last=c.lastOrderAt?new Date(c.lastOrderAt):null;if(from&&(!last||last<from))return false;if(to&&(!last||last>to))return false;return true});if(state.custSort==='name')list=[...list].sort((a,b)=>String(a.name).localeCompare(String(b.name)));else if(state.custSort==='spent')list=[...list].sort((a,b)=>(b.totalSpent||0)-(a.totalSpent||0));else if(state.custSort==='orders')list=[...list].sort((a,b)=>(b.orderCount||0)-(a.orderCount||0));else list=[...list].sort((a,b)=>new Date(b.lastOrderAt)-new Date(a.lastOrderAt));return list}
function notesText(c){if(Array.isArray(c.notes))return c.notes.map(n=>n.text).join(' ');return c.notes||''}
function orderSources(){return[...new Set(state.orders.map(o=>o.source).filter(Boolean))].sort()}
function filteredOrders(){const q=state.pipeQ.trim().toLowerCase();const from=state.pipeFrom?new Date(state.pipeFrom):null;const to=state.pipeTo?new Date(state.pipeTo+'T23:59:59'):null;return state.orders.filter(o=>{if(!!o.archived!==!!state.pipeShowArchived)return false;if(q){const hay=[o.customerName,o.phone,o.altPhone,o.email,o.externalId,o.id,o.address,o.town,o.province].join(' ').toLowerCase();if(!hay.includes(q))return false}if(state.pipeAssignee){if(state.pipeAssignee==='__unassigned'){if(o.assignedTo)return false}else if(o.assignedTo!==state.pipeAssignee)return false}if(state.pipeSource&&o.source!==state.pipeSource)return false;const created=o.createdAt?new Date(o.createdAt):null;if(from&&(!created||created<from))return false;if(to&&(!created||created>to))return false;return true})}
function whatsappHref(phone){const digits=String(phone||'').replace(/[^\d]/g,'');return digits?`https://wa.me/${digits}`:''}
function downloadCustomersCSV(){const cols=['Name','Phone','Alt phone','Email','Address','Town','Province','Source','Orders','Total spent','Last order','Notes'];const rows=state.customers.map(c=>[c.name,c.phone,c.altPhone||'',c.email||'',c.address||'',c.town||'',c.province||'',c.source||'',c.orderCount||0,Number(c.totalSpent||0).toFixed(2),c.lastOrderAt?new Date(c.lastOrderAt).toLocaleString():'',notesText(c)]);const csv=[cols,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='godwyn-contacts-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);showToast('Contacts exported')}
function csvCell(v){const s=String(v??'');return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function startCreateTask(){state.creatingTask=true;render()}function cancelCreateTask(){state.creatingTask=false;render()}
async function submitNewTask(f){const d=new FormData(f),body={title:(d.get('title')||'').trim(),description:(d.get('description')||'').trim(),assignedTo:d.get('assignedTo')||null,dueDate:d.get('dueDate')||null,priority:d.get('priority')||'medium',relatedOrderId:(d.get('relatedOrderId')||'').trim()};if(!body.title)return showToast('Task title is required');try{const t=await api('/api/tasks',{method:'POST',body});state.tasks.unshift(t);state.creatingTask=false;await loadAppData();showToast('Order handling task assigned');render()}catch(e){showToast(e.message)}}
