async function reassignTask(id,userId){try{const t=await api('/api/tasks/'+id,{method:'PATCH',body:{assignedTo:userId||null}});const i=state.tasks.findIndex(x=>x.id===id);state.tasks[i]=t;await loadAppData();showToast('Task reassigned')}catch(e){showToast(e.message)}}
async function deleteTask(id){if(!confirm('Delete this task?'))return;try{await api('/api/tasks/'+id,{method:'DELETE'});state.tasks=state.tasks.filter(x=>x.id!==id);showToast('Task deleted');render()}catch(e){showToast(e.message)}}
function startCreateUser(){state.creatingUser=true;render()}function cancelCreateUser(){state.creatingUser=false;render()}
async function submitNewUser(f){const d=new FormData(f),body={username:(d.get('username')||'').trim(),password:(d.get('password')||'').trim(),name:(d.get('name')||'').trim(),role:d.get('role')||'agent'};try{const u=await api('/api/admin/users',{method:'POST',body});state.users.push(u);state.creatingUser=false;showToast('User created');render()}catch(e){showToast(e.message)}}
async function toggleUserActive(id,active){try{const u=await api('/api/admin/users/'+id,{method:'PATCH',body:{active}});const i=state.users.findIndex(x=>x.id===id);state.users[i]=u;render()}catch(e){showToast(e.message)}}
async function deleteUser(id){if(!confirm('Remove this user? Assigned work will become unassigned.'))return;try{await api('/api/admin/users/'+id,{method:'DELETE'});state.users=state.users.filter(x=>x.id!==id);await loadAppData();render()}catch(e){showToast(e.message)}}
async function loadReport(){try{state.report=await api('/api/admin/reports/overview');state.activity=await api('/api/admin/reports/activity?limit=250');state.reportOpen=true;state.tab='reports';render()}catch(e){showToast(e.message)}}
async function refreshReport(){await loadReport();showToast('Report refreshed')}
function money(n,c){return (c?c+' ':'')+Number(n||0).toFixed(2)}
function dt(v){return v?new Date(v).toLocaleString():'—'}
function duration(m){if(!m)return '0 min';if(m<60)return m.toFixed(1)+' min';return Math.floor(m/60)+'h '+Math.round(m%60)+'m'}
function badge(s){return `<span class="badge ${escapeHtml(s)}">${escapeHtml(String(s||'').replaceAll('_',' '))}</span>`}
async function createVendor(f){const d=new FormData(f);try{const r=await api('/api/platform/vendors',{method:'POST',body:{companyName:(d.get('companyName')||'').trim(),name:(d.get('name')||'').trim(),username:(d.get('username')||'').trim(),password:(d.get('password')||'').trim(),plan:d.get('plan')||'starter'}});state.vendors.unshift({...r.vendor,userCount:1,orderCount:0,customerCount:0,integrationKey:r.integrationKey});state.creatingVendor=false;showToast('Vendor created — save the integration key securely');render()}catch(e){showToast(e.message)}}
async function deleteVendorPermanently(id){const v=state.vendors.find(x=>x.id===id);if(!v)return;const typed=prompt(`PERMANENT DELETE.\n\nThis erases "${v.name}" forever, including its ${v.userCount} user(s), ${v.orderCount} order(s), ${v.customerCount} customer(s), tasks and activity. This cannot be undone.\n\nType the vendor name exactly to confirm:`);if(typed===null)return;try{const r=await api('/api/platform/vendors/'+id,{method:'DELETE',body:{confirmName:typed}});state.vendors=state.vendors.filter(x=>x.id!==id);await loadAppData();showToast(`Vendor deleted (${r.deleted.orders} orders, ${r.deleted.customers} customers removed)`);render()}catch(e){showToast(e.message)}}
async function clearVendorCustomers(id){const v=state.vendors.find(x=>x.id===id);if(!v)return;if(!v.customerCount)return showToast('This vendor has no customers');if(!confirm(`Delete the ENTIRE customer list of "${v.name}" (${v.customerCount} customers)? Their orders stay, but contact details and notes are erased. This cannot be undone.`))return;try{const r=await api('/api/platform/vendors/'+id+'/customers/clear',{method:'POST',body:{confirm:true}});const i=state.vendors.findIndex(x=>x.id===id);if(i>=0)state.vendors[i].customerCount=0;state.customers=state.customers.filter(c=>c.vendorId!==id);showToast(`${r.deleted} customers deleted`);render()}catch(e){showToast(e.message)}}
async function deleteCustomer(id){const c=state.customers.find(x=>x.id===id);if(!c)return;if(!confirm(`Permanently delete customer "${c.name}"? Their orders stay. This cannot be undone.`))return;try{await api('/api/platform/customers/'+id,{method:'DELETE'});state.customers=state.customers.filter(x=>x.id!==id);showToast('Customer deleted');render()}catch(e){showToast(e.message)}}
async function toggleVendorService(id,active){if(!confirm(`${active?'Start':'Stop'} this vendor service? ${active?'The vendor will be able to log in again.':'The vendor users will be blocked from logging in and the store integration will stop accepting orders.'}`))return;try{const v=await api('/api/platform/vendors/'+id,{method:'PATCH',body:{active}});const i=state.vendors.findIndex(x=>x.id===id);if(i>=0)state.vendors[i]={...state.vendors[i],...v};showToast(`Vendor service ${active?'started':'stopped'}`);render()}catch(e){showToast(e.message)}}

function renderVendorsTab(){return `<div class="section-head"><div><h2>Vendors</h2><span class="muted">Each vendor has an isolated CRM workspace and integration key.</span></div><button class="btn" onclick="state.creatingVendor=true;render()">+ Add vendor</button></div>${state.resetRequests.length?`<div class="panel"><h3>Password reset requests</h3><p class="muted">A vendor who forgot a password can request help from the login screen. Set a temporary password here and send it to them securely.</p>${state.resetRequests.map(r=>`<div class="reset-row"><div><strong>${escapeHtml(r.username)}</strong><div class="muted">${escapeHtml(r.vendor?.name||'Vendor')} · requested ${dt(r.createdAt)}</div></div><button class="btn small" onclick="completeResetRequest('${r.id}')">Set temporary password</button></div>`).join('')}</div>`:''}${state.creatingVendor?`<div class="panel"><h3>New vendor</h3><form onsubmit="event.preventDefault();createVendor(this)"><div class="form-grid"><div class="field"><label>Company / store</label><input name="companyName" required></div><div class="field"><label>Owner name</label><input name="name" required></div><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Temporary password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Plan</label><select name="plan"><option value="starter">Starter</option><option value="business">Business</option><option value="enterprise">Enterprise</option></select></div></div><button class="btn">Create vendor</button> <button class="btn ghost" type="button" onclick="state.creatingVendor=false;render()">Cancel</button></form></div>`:''}${state.vendors.map(v=>`<div class="panel"><div class="section-head"><div><h3 style="margin:0">${escapeHtml(v.name)}</h3><span class="muted">${escapeHtml(v.plan)} · ${v.active?'Active':'Stopped'} · ${escapeHtml(v.subscriptionStatus||'trialing')} · created ${dt(v.createdAt)}</span></div><strong>${v.orderCount} orders</strong></div><p class="muted">${v.userCount} users · ${v.customerCount} customers</p><div class="row-actions"><button class="btn small ${v.active?'alert':'ghost'}" onclick="toggleVendorService('${v.id}',${!v.active})">${v.active?'⏹ Stop vendor service':'▶ Start vendor service'}</button><button class="btn small ghost" onclick="clearVendorCustomers('${v.id}')">🧹 Delete customer list (${v.customerCount})</button><button class="btn small alert" onclick="deleteVendorPermanently('${v.id}')">🗑 Delete vendor permanently</button><label class="field inline-field"><span>Plan</span><select onchange="changeVendorPlan('${v.id}',this.value)"><option value="starter" ${v.plan==='starter'?'selected':''}>Starter</option><option value="business" ${v.plan==='business'?'selected':''}>Business</option><option value="enterprise" ${v.plan==='enterprise'?'selected':''}>Enterprise</option></select></label><label class="field inline-field"><span>Status</span><select onchange="changeVendorSubscription('${v.id}',this.value)"><option value="trialing" ${v.subscriptionStatus==='trialing'?'selected':''}>Trialing</option><option value="active" ${v.subscriptionStatus==='active'?'selected':''}>Active</option><option value="past_due" ${v.subscriptionStatus==='past_due'?'selected':''}>Past due</option><option value="cancelled" ${v.subscriptionStatus==='cancelled'?'selected':''}>Cancelled</option></select></label></div>${v.integrationKey?`<div class="field"><label>Integration key</label><input readonly value="${escapeHtml(v.integrationKey)}" onclick="this.select()"></div>`:''}</div>`).join('')||'<div class="empty-state">No vendors yet.</div>'}`}
function topbar(){return `<div class="topbar"><div><p class="brand">QuiverCRM<small>${state.me?escapeHtml(state.me.name)+' · '+escapeHtml(state.me.role):'Sales & task management'}</small></p></div>${state.me?'<div class="topbar-right"><span class="redis-pill">● CRM connected</span><a class="icon-link" href="#" onclick="event.preventDefault();logout()">Log out</a></div>':''}</div>`}
async function saveVendorProfile(f){const d=new FormData(f);try{state.vendor=await api('/api/vendor/profile',{method:'PATCH',body:{name:(d.get('name')||'').trim(),slug:(d.get('slug')||'').trim()}});showToast('Workspace updated');render()}catch(e){showToast(e.message)}}
async function changeVendorPlan(id,plan){try{const v=await api('/api/platform/vendors/'+id,{method:'PATCH',body:{plan}});const i=state.vendors.findIndex(x=>x.id===id);if(i>=0)state.vendors[i]={...state.vendors[i],...v};showToast('Plan updated');render()}catch(e){showToast(e.message)}}
async function changeVendorSubscription(id,subscriptionStatus){try{const v=await api('/api/platform/vendors/'+id,{method:'PATCH',body:{subscriptionStatus}});const i=state.vendors.findIndex(x=>x.id===id);if(i>=0)state.vendors[i]={...state.vendors[i],...v};showToast('Subscription status updated');render()}catch(e){showToast(e.message)}}

function renderSubscriptionTab(){const s=state.subscription;if(!s)return '<div class="empty-state">Subscription information unavailable.</div>';const status=s.vendor.subscriptionStatus;const trial=s.renewal.trialEndsAt?new Date(s.renewal.trialEndsAt):null;const pct=s.plan.monthlyOrders===Infinity?0:Math.min(100,(s.usage.monthlyOrders/s.plan.monthlyOrders)*100);return `<div class="section-head"><div><h2>Subscription & plan</h2><span class="muted">Manage your QuiverCRM workspace and usage.</span></div></div><div class="metrics"><div><strong>${escapeHtml(s.plan.name)}</strong><span>Current plan</span></div><div><strong>${escapeHtml(status)}</strong><span>Subscription status</span></div><div><strong>${s.usage.users}/${s.plan.users===Infinity?'∞':s.plan.users}</strong><span>Active users</span></div><div><strong>${s.usage.monthlyOrders}/${s.plan.monthlyOrders===Infinity?'∞':s.plan.monthlyOrders}</strong><span>Orders this month</span></div></div><div class="panel"><h3>14-day trial</h3><p>${trial&&!isNaN(trial)?(status==='trialing'?'Trial ends '+dt(trial.toISOString()):'Trial ended '+dt(trial.toISOString())):'Trial information unavailable.'}</p><div class="progress"><div style="width:${pct}%"></div></div><p class="muted small-line">Order usage this month: ${s.usage.monthlyOrders} of ${s.plan.monthlyOrders===Infinity?'unlimited':s.plan.monthlyOrders}.</p></div><div class="panel"><h3>Workspace settings</h3><form onsubmit="event.preventDefault();saveVendorProfile(this)"><div class="form-grid"><div class="field"><label>Business name</label><input name="name" value="${escapeHtml(state.vendor.name)}" required></div><div class="field"><label>Workspace slug</label><input name="slug" value="${escapeHtml(state.vendor.slug)}" required></div></div><button class="btn">Save settings</button></form></div><div class="panel"><h3>Upgrade your plan</h3><p class="muted">Plan changes are available now. Payment gateway and automatic billing can be connected separately.</p><div class="plan-grid"><div><strong>Starter</strong><p>500 orders/month · 2 users · 1 store</p>${s.plan.id!=='starter'?'<button class="btn small ghost" onclick="changeMyPlan(\'starter\')">Change to Starter</button>':''}</div><div><strong>Business</strong><p>5,000 orders/month · 10 users · 3 stores</p>${s.plan.id==='business'?'<span class="muted">Current plan</span>':`<button class="btn small" onclick="changeMyPlan('business')">Upgrade to Business</button>`}</div><div><strong>Enterprise</strong><p>Unlimited orders, users and stores</p>${s.plan.id==='enterprise'?'<span class="muted">Current plan</span>':`<button class="btn small" onclick="changeMyPlan('enterprise')">Upgrade to Enterprise</button>`}</div></div></div>`}
function renderAuth(a){const setup=!state.hasAdmin&&state.authMode!=='signup'&&state.authMode!=='forgot';const signup=state.authMode==='signup';const forgot=state.authMode==='forgot';a.innerHTML=`${topbar()}<div class="wrap"><div class="login-wrap"><h2>${forgot?'Reset your password':signup?'Start your QuiverCRM trial':setup?'Set up QuiverCRM':'Log in'}</h2><p class="muted">${forgot?'Enter your username and we will create a secure reset request for the QuiverCRM administrator.':signup?'Create a vendor workspace and get 14 days to try QuiverCRM.':setup?'Create the first administrator account.':'Access your CRM workspace.'}</p><form onsubmit="event.preventDefault();handleAuthSubmit(this)">${signup||setup?'<div class="field"><label>Store / company name</label><input name="companyName" required></div><div class="field"><label>Your name</label><input name="name" required></div>':''}<div class="field"><label>Username</label><input name="username" required></div>${setup?'<div class="field"><label>Private setup key</label><input name="setupKey" type="password" required></div>':''}${!forgot?'<div class="field"><label>Password</label><input name="password" type="password" required minlength="'+(signup||setup?10:1)+'"></div>':''}<button class="btn full">${forgot?'Request password reset':signup?'Start free trial':setup?'Create admin account':'Log in'}</button>${state.authError?`<p class="error-text">${escapeHtml(state.authError)}</p>`:''}</form>${!setup&&!signup&&!forgot?`<button class="btn ghost full" style="margin-top:10px" onclick="requestResetFromLogin()">Forgot password?</button><button class="btn ghost full" style="margin-top:10px" onclick="state.authMode='signup';render()">Create a new vendor account</button>`:''}${forgot?`<button class="btn ghost full" style="margin-top:10px" onclick="state.authMode='login';state.authError='';render()">Back to login</button>`:''}${signup?`<button class="btn ghost full" style="margin-top:10px" onclick="state.authMode='login';render()">Back to login</button>`:''}</div></div>`}
function renderApp(a){const admin=state.me.role==='admin',platform=!!state.me.platformAdmin,newOrders=state.orders.filter(o=>o.pipelineStage==='new').length,open=state.tasks.filter(t=>t.status!=='done'&&(admin||t.assignedTo===state.me.id)).length;a.innerHTML=`${topbar()}<div class="wrap">${state.dataWarning?`<div class="panel"><strong>Data loading warning</strong><p class="muted">${escapeHtml(state.dataWarning)}</p><button class="btn small" onclick="retryApp()">Retry data load</button></div>`:''}<div class="top-admin-bar"><div><h2 style="margin:0">${platform?'QuiverCRM Platform':admin?'Vendor dashboard':'My workspace'}</h2><span class="muted">${state.vendor?escapeHtml(state.vendor.name):'Workspace'} · ${newOrders} new orders · ${open} open tasks</span></div>${admin?'<button class="btn" onclick="loadReport()">One-click reports</button>':''}</div><div class="tabbar"><button class="${state.tab==='orders'?'active':''}" onclick="state.tab='orders';render()">Pipeline</button><button class="${state.tab==='contacts'?'active':''}" onclick="state.tab='contacts';state.selectedContactId=null;render()">Contacts</button><button class="${state.tab==='customers'?'active':''}" onclick="state.tab='customers';render()">Customers</button><button class="${state.tab==='tasks'?'active':''}" onclick="state.tab='tasks';render()">${admin?'Order Tasks':'My Tasks'}</button>${admin?`<button class="${state.tab==='reports'?'active':''}" onclick="loadReport()">Reports & Analytics</button><button class="${state.tab==='users'?'active':''}" onclick="state.tab='users';render()">Users</button>${!platform?`<button class="${state.tab==='subscription'?'active':''}" onclick="state.tab='subscription';render()">Plan & Billing</button>`:''}`:''}${platform?`<button class="${state.tab==='vendors'?'active':''}" onclick="state.tab='vendors';render()">Vendors</button>`:''}</div>${state.tab==='orders'?renderOrdersTab():''}${state.tab==='contacts'?renderContactsSafe():''}${state.tab==='customers'?renderCustomersTab():''}${state.tab==='tasks'?renderTasksTab(admin):''}${state.tab==='reports'&&admin?renderReportsTab():''}${state.tab==='users'&&admin?renderUsersTab():''}${state.tab==='vendors'&&platform?renderVendorsTab():''}${state.tab==='subscription'&&admin?renderSubscriptionTab():''}</div>${toastHtml()}`}
async function requestResetFromLogin(){
  state.authMode='forgot';state.authError='';render();
}
async function completeResetRequest(id){
  const password=prompt('Enter a temporary password (at least 8 characters) for this user:');
  if(password===null)return;
  if(String(password).length<8)return showToast('Temporary password must be at least 8 characters');
  try{await api('/api/platform/password-reset-requests/'+id+'/complete',{method:'POST',body:{password}});state.resetRequests=state.resetRequests.filter(r=>r.id!==id);showToast('Password reset completed');render()}catch(e){showToast(e.message)}
}
async function changeMyPlan(plan){
  try{state.subscription=await api('/api/vendor/plan',{method:'PATCH',body:{plan}});showToast('Plan updated');render()}catch(e){showToast(e.message)}
}
function renderError(a){a.innerHTML=`${topbar()}<div class="wrap"><div class="panel"><h2>QuiverCRM</h2><p class="error-text">${escapeHtml(state.serverError||'The CRM could not be loaded.')}</p><p class="muted">Your data has not been intentionally removed. This may be a temporary server or connection problem.</p><button class="btn" onclick="init()">Retry</button></div></div>`}
function render(){
  const a=document.getElementById('app');
  if(!a)return;
  if(state.loading){a.innerHTML='<div class="wrap"><p class="muted">Loading QuiverCRM…</p></div>';return}
  if(state.view==='auth')return renderAuth(a);
  if(state.view==='error')return renderError(a);
  if(!state.me){state.view='auth';return renderAuth(a)}
  return renderApp(a);
}

function renderContactsSafe(){try{const html=renderContactsTab();return typeof html==='string'&&html.trim()?html:'<div class="empty-state">No contacts available.</div>';}catch(e){console.error('Contacts render failed:',e);return '<div class="panel"><h3>Contacts</h3><p class="error-text">Contacts could not be displayed. Please refresh the CRM.</p></div>';}}

function renderOrderItems(o){const items=Array.isArray(o.items)?o.items:[];if(!items.length)return '';return `<div class="muted order-items">${items.map(i=>`${i.qty||1}× ${escapeHtml(i.name||'Unnamed item')}${i.price?' — '+money(i.price,o.currency):''}`).join('<br>')}</div>`}
function renderOrderCard(o,assignedUsers){const adminActions=state.me.role==='admin'?`<select onchange="assignOrder('${o.id}',this.value)"><option value="">Assign...</option>${assignedUsers.map(u=>`<option value="${u.id}" ${o.assignedTo===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select>${o.archived?`<button class="btn ghost small" onclick="unarchiveOrder('${o.id}')">♻ Restore</button>`:`<button class="btn ghost small" onclick="archiveOrder('${o.id}')">📦 Archive</button>`}<button class="btn ghost danger small" onclick="deleteOrder('${o.id}')">🗑 Delete</button>`:'';const contactLine=[o.phone||'No phone',o.altPhone?'Alt: '+o.altPhone:'',o.email||''].filter(Boolean).join(' · ');const locLine=[o.address||'',[o.town,o.province].filter(Boolean).join(', ')].filter(Boolean).join(' · ');const deliveryLine=[o.deliveryDate?'Preferred date: '+o.deliveryDate:'',o.deliveryWindow?'Window: '+o.deliveryWindow:''].filter(Boolean).join(' · ');return `<div class="order-card">${o.archived?`<span class="badge archived">Archived${o.archivedAt?' · '+dt(o.archivedAt):''}</span>`:''}<div class="order-title">${escapeHtml(o.externalId||o.id)}</div><div class="muted">${escapeHtml(o.customerName)} · ${dt(o.createdAt)}${o.source?' · '+escapeHtml(o.source):''}</div>${renderOrderItems(o)}<div class="order-money">${money(o.total,o.currency)}</div><div class="muted">${escapeHtml(contactLine)}</div>${locLine?`<div class="muted">${escapeHtml(locLine)}</div>`:''}${deliveryLine?`<div class="muted">${escapeHtml(deliveryLine)}</div>`:''}${o.notes?`<div class="muted">Note: ${escapeHtml(o.notes)}</div>`:''}<div class="muted">${o.assignedToName?'Assigned: '+escapeHtml(o.assignedToName):'Unassigned'}</div><div class="row-actions"><select onchange="setOrderStage('${o.id}',this.value)">${STAGES.map(s=>`<option value="${s}" ${s===(o.pipelineStage||o.status)?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select>${o.pipelineStage==='won'?`<button class="btn small ghost" onclick="viewReceipt('${o.id}')">🧾 ${o.receiptNumber?'View Receipt':'Generate Receipt'}</button><button class="btn small ghost" onclick="printReceipt('${o.id}')">🖨 Print / PDF</button><button class="btn small ghost" onclick="whatsappReceipt('${o.id}')">💬 WhatsApp</button>`:''}${adminActions}</div><div class="muted small-line">${o.handlingStartedAt?'Handling started '+dt(o.handlingStartedAt):'Not yet handled'}${o.completedAt?' · completed '+dt(o.completedAt):''}</div></div>`}
function renderPipelineFilters(){const assignedUsers=state.users.filter(u=>u.active);return `<div class="panel filter-bar"><div class="field"><label>Search</label><input type="text" placeholder="Customer, phone, order ID…" value="${escapeHtml(state.pipeQ)}" oninput="setPipeField('pipeQ',this.value)"></div>${state.me.role==='admin'?`<div class="field"><label>Assigned to</label><select onchange="setPipeField('pipeAssignee',this.value)"><option value="">Everyone</option><option value="__unassigned" ${state.pipeAssignee==='__unassigned'?'selected':''}>Unassigned</option>${assignedUsers.map(u=>`<option value="${u.id}" ${state.pipeAssignee===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Category</label><select onchange="setPipeField('pipeSource',this.value)"><option value="">All sources</option>${orderSources().map(s=>`<option value="${escapeHtml(s)}" ${state.pipeSource===s?'selected':''}>${escapeHtml(s)}</option>`).join('')}</select></div><div class="field"><label>Created from</label><input type="date" value="${escapeHtml(state.pipeFrom)}" onchange="setPipeField('pipeFrom',this.value)"></div><div class="field"><label>Created to</label><input type="date" value="${escapeHtml(state.pipeTo)}" onchange="setPipeField('pipeTo',this.value)"></div>${state.me.role==='admin'?`<div class="field"><label>&nbsp;</label><label class="check-inline"><input type="checkbox" ${state.pipeShowArchived?'checked':''} onchange="setPipeField('pipeShowArchived',this.checked)"> Show archived</label></div>`:''}</div>`}
function renderStagePage(stage,assignedUsers){const os=filteredOrders().filter(o=>(o.pipelineStage||o.status)==stage);return `${renderPipelineFilters()}<div class="section-head"><div><h2 style="margin:0;text-transform:capitalize">${escapeHtml(stage.replaceAll('_',' '))}</h2><span class="muted">${os.length} order${os.length===1?'':'s'}</span></div><button class="btn ghost" onclick="backToPipeline()">← Back to pipeline</button></div>${os.map(o=>renderOrderCard(o,assignedUsers)).join('')||'<div class="empty-state">No orders match your search/filters in this stage</div>'}`}
function renderOrdersTab(){if(!state.orders.length)return '<div class="empty-state">No orders yet. Connected stores will send orders here.</div>';const assignedUsers=state.users.filter(u=>u.active);if(state.viewingStage)return renderStagePage(state.viewingStage,assignedUsers);const os=filteredOrders();return `${renderPipelineFilters()}<div class="pipeline-board">${STAGES.map(stage=>{const c=os.filter(o=>(o.pipelineStage||o.status)==stage);return `<div class="pipeline-col" style="cursor:pointer" onclick="viewStage('${stage}')" title="Click to view order details"><div class="pipeline-head"><strong>${escapeHtml(stage.replaceAll('_',' '))}</strong><span>${c.length} order${c.length===1?'':'s'}</span></div></div>`}).join('')}</div>`}
function renderCustomerNotes(c){const notes=Array.isArray(c.notes)?c.notes:(c.notes?[{id:'legacy',text:c.notes,authorName:'Unknown',at:c.lastOrderAt}]:[]);if(!notes.length)return '<p class="muted small-line">No notes yet.</p>';return `<div class="notes-list">${notes.map(n=>`<div class="note-row"><div>${escapeHtml(n.text)}</div><div class="muted small-line">${escapeHtml(n.authorName||'Unknown')} · ${dt(n.at)}</div></div>`).join('')}</div>`}
function renderContactDetail(c){if(!c)return '';const orders=Array.isArray(c.orders)?c.orders:contactOrderMatches(c);const interactions=Array.isArray(c.interactions)?c.interactions:[];const admin=state.me.role==='admin';return `<div class="section-head"><div><button class="btn ghost small" onclick="closeContact()">← Contacts</button><h2 style="margin:12px 0 2px">${escapeHtml(c.name)}</h2><span class="muted">${escapeHtml(c.company||c.type||'Contact')} · ${escapeHtml(c.phone||'No phone')}</span></div><div class="row-actions"><a class="btn small ghost" href="tel:${escapeHtml(c.phone||'')}">📞 Call</a>${c.phone?`<a class="btn small ghost" target="_blank" rel="noopener" href="https://wa.me/${String(c.phone).replace(/\D/g,'')}">💬 WhatsApp</a>`:''}${c.email?`<a class="btn small ghost" href="mailto:${escapeHtml(c.email)}">✉ Email</a>`:''}</div></div><div class="contact-profile-grid"><div class="panel"><h3>Contact details</h3><div class="contact-detail-list"><div><span>Phone</span><strong>${escapeHtml(c.phone||'—')}</strong></div><div><span>Email</span><strong>${escapeHtml(c.email||'—')}</strong></div><div><span>Location</span><strong>${escapeHtml([c.town,c.province].filter(Boolean).join(', ')||'—')}</strong></div><div><span>Source</span><strong>${escapeHtml(c.source||'—')}</strong></div><div><span>Assigned to</span><strong>${escapeHtml(c.assignedToName||'Unassigned')}</strong></div><div><span>Last contacted</span><strong>${escapeHtml(c.lastContactedAt?dt(c.lastContactedAt):'Never')}</strong></div></div><div class="row-actions" style="margin-top:14px"><select onchange="updateContact('${c.id}',{status:this.value})">${['new','contacted','interested','follow_up','qualified','converted','lost'].map(x=>`<option value="${x}" ${c.status===x?'selected':''}>${contactStatusLabel(x)}</option>`).join('')}</select><select onchange="updateContact('${c.id}',{priority:this.value})">${['low','medium','high'].map(x=>`<option ${c.priority===x?'selected':''}>${x}</option>`).join('')}</select>${admin?`<button class="btn small alert" onclick="deleteContact('${c.id}')">Delete</button>`:''}</div></div><div class="panel"><h3>Log contact</h3><form onsubmit="event.preventDefault();logContactInteraction('${c.id}',this)"><div class="form-grid"><div class="field"><label>Method</label><select name="method"><option value="call">Phone call</option><option value="whatsapp">WhatsApp</option><option value="sms">SMS</option><option value="email">Email</option><option value="meeting">Meeting</option><option value="other">Other</option></select></div><div class="field"><label>Disposition</label><select name="disposition" required><option value="">Select outcome…</option>${['interested','very_interested','follow_up_required','call_back_later','not_interested','no_answer','busy','wrong_number','converted','lost'].map(x=>`<option value="${x}">${dispositionLabel(x)}</option>`).join('')}</select></div><div class="field"><label>Next follow-up</label><input name="nextFollowUp" type="datetime-local"></div></div><div class="field"><label>Interaction notes</label><textarea name="note" placeholder="What happened? What does the contact need next?"></textarea></div><button class="btn">Save interaction</button></form></div></div><div class="panel"><h3>Interaction history</h3>${interactions.length?`<div class="timeline">${interactions.map(i=>`<div class="timeline-item"><div class="timeline-dot"></div><div><strong>${escapeHtml(dispositionLabel(i.disposition))}</strong><span class="muted"> · ${escapeHtml(i.method)} · ${dt(i.at)}</span><div>${escapeHtml(i.note||'No notes')}</div><div class="muted small-line">${escapeHtml(i.userName||'CRM user')}</div></div></div>`).join('')}</div>`:'<div class="empty-state">No contact interactions recorded yet.</div>'}</div><div class="panel"><h3>Sales pipeline & orders</h3>${orders.length?orders.map(o=>`<div class="contact-order-row"><div><strong>${escapeHtml(o.externalId||o.id)}</strong><span class="muted"> · ${escapeHtml(o.customerName||c.name)} · ${dt(o.createdAt)}</span></div><div>${badge(o.pipelineStage||o.status)} <strong>${money(o.total,o.currency)}</strong></div></div>`).join(''):'<div class="empty-state">No orders linked to this contact yet. The existing sales pipeline remains unchanged.</div>'}</div>`}
function renderContactsTab(){if(state.selectedContactId){const c=state.contacts.find(x=>x.id===state.selectedContactId);return c?renderContactDetail(c):'<div class="empty-state">Contact not found.</div>'}const admin=state.me.role==='admin';const list=filteredContacts();const due=state.contacts.filter(c=>c.nextFollowUp&&new Date(c.nextFollowUp)<=new Date()).length;const overdue=state.contacts.filter(c=>c.nextFollowUp&&new Date(c.nextFollowUp)<new Date()).length;const toolbar=`<div class="metrics"><div><strong>${state.contacts.length}</strong><span>Total contacts</span></div><div><strong>${state.contacts.filter(c=>c.status==='new').length}</strong><span>New</span></div><div><strong>${state.contacts.filter(c=>c.status==='interested').length}</strong><span>Interested</span></div><div><strong>${due}</strong><span>Follow-ups due</span></div><div><strong>${state.contacts.filter(c=>c.status==='converted').length}</strong><span>Converted</span></div></div><div class="panel filter-bar"><div class="field"><label>Search</label><input placeholder="Name, company, phone, email…" value="${escapeHtml(state.contactQ||'')}" oninput="setContactField('contactQ',this.value)"></div><div class="field"><label>Status</label><select onchange="setContactField('contactStatus',this.value)"><option value="">All statuses</option>${['new','contacted','interested','follow_up','qualified','converted','lost'].map(x=>`<option value="${x}" ${state.contactStatus===x?'selected':''}>${contactStatusLabel(x)}</option>`).join('')}</select></div><div class="field"><label>Assigned</label><select onchange="setContactField('contactAssignee',this.value)"><option value="">Everyone</option>${state.users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${state.contactAssignee===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Source</label><select onchange="setContactField('contactSource',this.value)"><option value="">All sources</option>${contactSources().map(x=>`<option value="${escapeHtml(x)}" ${state.contactSource===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select onchange="setContactField('contactPriority',this.value)"><option value="">All</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></div><div class="field"><label>Follow-up</label><select onchange="setContactField('contactFollow',this.value)"><option value="">Any</option><option value="due">Due now</option><option value="overdue">Overdue</option></select></div></div><div class="row-actions contact-toolbar"><button class="btn" onclick="state.creatingContact=true;render()">+ Add Contact</button><label class="btn ghost" style="cursor:pointer">⬆ Import CSV<input type="file" accept=".csv,text/csv" onchange="handleContactsCSV(this)" hidden></label><button class="btn ghost" onclick="downloadContactsCSV()">⬇ Export CSV</button></div>${state.creatingContact?`<div class="panel"><h3>Add contact</h3><form onsubmit="event.preventDefault();createContact(this)"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Company</label><input name="company"></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Alternative phone</label><input name="altPhone"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Town/City</label><input name="town"></div><div class="field"><label>Province</label><input name="province"></div><div class="field"><label>Type</label><select name="type"><option value="lead">Lead</option><option value="prospect">Prospect</option><option value="customer">Customer</option><option value="partner">Partner</option><option value="supplier">Supplier</option><option value="other">Other</option></select></div><div class="field"><label>Source</label><input name="source" placeholder="Facebook, referral, CSV…"></div><div class="field"><label>Assigned to</label><select name="assignedTo"><option value="">Unassigned</option>${state.users.filter(u=>u.active).map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('')}</select></div></div><button class="btn">Create contact</button> <button class="btn ghost" type="button" onclick="state.creatingContact=false;render()">Cancel</button></form></div>`:''}<div class="panel"><div class="section-head"><div><h2>Contacts</h2><span class="muted">${list.length} shown · ${overdue} overdue follow-up${overdue===1?'':'s'}</span></div></div>${list.length?`<div class="contact-table"><div class="contact-table-head"><span>Contact</span><span>Status</span><span>Assigned</span><span>Next action</span><span>Orders</span></div>${list.map(c=>`<button class="contact-row" onclick="openContact('${c.id}')"><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.company||c.phone||'')} · ${escapeHtml(c.source||'—')}</small></span><span>${badge(c.status)}<small>${escapeHtml(c.priority||'medium')} priority</small></span><span>${escapeHtml(c.assignedToName||'Unassigned')}</span><span>${c.nextFollowUp?dt(c.nextFollowUp):'No follow-up set'}</span><span>${c.ordersCount||0}</span></button>`).join('')}</div>`:'<div class="empty-state">No contacts match your filters.</div>'}</div>`;return toolbar;}

function renderCustomersTab(){const admin=state.me.role==='admin';const toolbar=`<div class="panel filter-bar"><div class="field"><label>Search</label><input type="text" placeholder="Name, phone, address, notes…" value="${escapeHtml(state.custQ)}" oninput="setCustField('custQ',this.value)"></div><div class="field"><label>Category</label><select onchange="setCustField('custSource',this.value)"><option value="">All sources</option>${customerSources().map(s=>`<option value="${escapeHtml(s)}" ${state.custSource===s?'selected':''}>${escapeHtml(s)}</option>`).join('')}</select></div><div class="field"><label>Last order from</label><input type="date" value="${escapeHtml(state.custFrom)}" onchange="setCustField('custFrom',this.value)"></div><div class="field"><label>Last order to</label><input type="date" value="${escapeHtml(state.custTo)}" onchange="setCustField('custTo',this.value)"></div><div class="field"><label>Sort by</label><select onchange="setCustField('custSort',this.value)"><option value="recent" ${state.custSort==='recent'?'selected':''}>Most recent order</option><option value="name" ${state.custSort==='name'?'selected':''}>Name</option><option value="spent" ${state.custSort==='spent'?'selected':''}>Total spent</option><option value="orders" ${state.custSort==='orders'?'selected':''}>Order count</option></select></div>${admin?'<button class="btn ghost" onclick="downloadCustomersCSV()">⬇ Download contacts (CSV)</button>':''}</div>`;
  if(!state.customers.length)return toolbar+'<div class="empty-state">No customers yet.</div>';
  const list=filteredCustomers();
  const cards=list.map(c=>{const wa=whatsappHref(c.phone);const locLine=[c.town,c.province].filter(Boolean).join(', ');const extraLine=[c.altPhone?'Alt: '+c.altPhone:'',c.email||''].filter(Boolean).join(' · ');return `<div class="panel"><div class="section-head"><div><h3 style="margin:0">${escapeHtml(c.name)}</h3><span class="muted">${c.address?escapeHtml(c.address)+' · ':''}${locLine?escapeHtml(locLine)+' · ':''}${escapeHtml(c.source||'—')}</span></div><div>${c.orderCount} order${c.orderCount===1?'':'s'} · ${money(c.totalSpent,'')}</div></div><div class="muted small-line" style="margin-bottom:10px">${c.phone?`<a class="phone-pill" href="${wa}" target="_blank" rel="noopener" title="Open in WhatsApp">📞 ${escapeHtml(c.phone)}</a>`:'No phone'} ${c.lastOrderAt?'· last order '+dt(c.lastOrderAt):''}</div>${extraLine?`<div class="muted small-line" style="margin-bottom:10px">${escapeHtml(extraLine)}</div>`:''}${renderCustomerNotes(c)}<form onsubmit="event.preventDefault();addCustomerNote('${c.id}',this)"><div class="field"><label>Add a note</label><textarea name="notes" placeholder="Type a note…"></textarea></div><button class="btn small">Save note</button>${state.me.platformAdmin?` <button type="button" class="btn small alert" onclick="deleteCustomer('${c.id}')">🗑 Delete customer</button>`:''}</form></div>`}).join('')||'<div class="empty-state">No customers match your search/filters.</div>';
  return toolbar+cards;
}
function renderTasksTab(admin){
  const users=state.users.filter(u=>u.active);
  const form=admin ? `<div class="section-head"><h2>Order handling tasks</h2><button class="btn" onclick="startCreateTask()">+ Assign handling task</button></div>${state.creatingTask ? `<div class="panel"><h3>Assign order handling work</h3><form onsubmit="event.preventDefault();submitNewTask(this)"><div class="form-grid"><div class="field"><label>Task</label><input name="title" placeholder="Confirm order / call customer / arrange delivery" required></div><div class="field"><label>Assign to</label><select name="assignedTo"><option value="">Unassigned</option>${users.map(u=>`<option value="${u.id}">${escapeHtml(u.name)} (${u.role})</option>`).join('')}</select></div><div class="field"><label>Related order</label><select name="relatedOrderId"><option value="">None</option>${state.orders.map(o=>`<option value="${o.id}">${escapeHtml(o.externalId||o.id)} — ${escapeHtml(o.customerName)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select name="priority"><option>low</option><option selected>medium</option><option>high</option></select></div><div class="field"><label>Due date</label><input name="dueDate" type="date"></div></div><div class="field"><label>Instructions</label><textarea name="description"></textarea></div><button class="btn">Assign task</button> <button class="btn ghost" type="button" onclick="cancelCreateTask()">Cancel</button></form></div>` : ''}` : `<div class="section-head"><h2>My tasks</h2></div>`;
  if(!state.tasks.length)return form+'<div class="empty-state">No tasks yet.</div>';
  return form+state.tasks.map(t=>`<div class="panel"><div class="section-head"><div><h3 style="margin:0">${escapeHtml(t.title)} ${badge(t.priority)}</h3><span class="muted">${t.assignedToName?'Assigned to '+escapeHtml(t.assignedToName):'Unassigned'} · created ${dt(t.createdAt)}${t.startedAt?' · started '+dt(t.startedAt):''}${t.completedAt?' · done '+dt(t.completedAt):''}</span></div>${badge(t.status)}</div>${t.relatedOrderId?`<p class="muted">Order: ${escapeHtml(t.relatedOrderId)}</p>`:''}${t.description?`<p>${escapeHtml(t.description)}</p>`:''}<div class="row-actions"><select onchange="setTaskStatus('${t.id}',this.value)">${['open','in_progress','done'].map(s=>`<option ${t.status===s?'selected':''}>${s.replace('_',' ')}</option>`).join('')}</select>${admin?`<select onchange="reassignTask('${t.id}',this.value)"><option value="">Unassigned</option>${users.map(u=>`<option value="${u.id}" ${t.assignedTo===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select><button class="btn small alert" onclick="deleteTask('${t.id}')">Delete</button>`:''}</div></div>`).join('');
}
function renderReportsTab(){if(!state.report)return '<div class="empty-state">Loading report…</div>';const r=state.report;const ranked=[...r.users].sort((a,b)=>b.totalTaskMinutes-a.totalTaskMinutes);return `<div class="section-head"><div><h2>Management report</h2><span class="muted">Generated ${dt(r.generatedAt)}</span></div><button class="btn ghost" onclick="refreshReport()">Refresh</button></div><div class="metrics"><div><strong>${r.totals.orders}</strong><span>Total orders</span></div><div><strong>${r.totals.newOrders}</strong><span>New orders</span></div><div><strong>${r.totals.openTasks}</strong><span>Open tasks</span></div><div><strong>${r.totals.customers}</strong><span>Customers</span></div><div><strong>${r.totals.completedOrders}</strong><span>Completed orders</span></div><div><strong>${duration(r.totals.avgHandlingMinutes)}</strong><span>Avg handling time</span></div></div><div class="panel"><h3>Pipeline snapshot</h3><div class="stage-grid">${STAGES.map(s=>`<div>${badge(s)} <strong>${r.pipeline[s]||0}</strong></div>`).join('')}</div></div><div class="panel"><h3>Who is handling the most / least?</h3><table><thead><tr><th>User</th><th>Role</th><th>Orders</th><th>Tasks</th><th>Done</th><th>Total handling time</th><th>Avg completed task</th><th>Open</th><th>Activity</th><th>Busiest hour</th><th>Last activity</th></tr></thead><tbody>${ranked.map(u=>`<tr><td>${escapeHtml(u.name)}</td><td>${u.role}</td><td>${u.ordersHandled}</td><td>${u.tasks}</td><td>${u.tasksDone}</td><td>${duration(u.totalTaskMinutes)}</td><td>${duration(u.avgTaskMinutes)}</td><td>${u.openTasks}</td><td>${u.activityCount}</td><td>${u.busiestHour}</td><td>${dt(u.lastActivityAt)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h3>CRM user activity — exact timestamps</h3><p class="muted">Last ${state.activity.length} recorded actions. Use this to see exactly who did what and when.</p><div class="activity-list">${state.activity.map(a=>`<div class="activity-row"><div><strong>${escapeHtml(a.userName||'System')}</strong> <span>${escapeHtml(a.action.replaceAll('_',' '))}</span><div class="muted">${escapeHtml(a.entityType)} ${escapeHtml(a.entityId||'')}</div></div><time>${dt(a.at)}</time></div>`).join('')||'<div class="empty-state">No activity yet.</div>'}</div></div>`}
function renderUsersTab(){return `<div class="section-head"><h2>Users</h2><button class="btn" onclick="startCreateUser()">+ Add user</button></div>${state.creatingUser?`<div class="panel"><form onsubmit="event.preventDefault();submitNewUser(this)"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="8"></div><div class="field"><label>Role</label><select name="role"><option value="agent">Agent</option><option value="admin">Admin</option></select></div></div><button class="btn">Create user</button> <button class="btn ghost" type="button" onclick="cancelCreateUser()">Cancel</button></form></div>`:''}<table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${escapeHtml(u.name)}</td><td>${escapeHtml(u.username)}</td><td>${u.role}</td><td>${badge(u.active?'active':'inactive')}</td><td>${u.active?`<button class="btn small ghost" onclick="toggleUserActive('${u.id}',false)">Deactivate</button>`:`<button class="btn small ghost" onclick="toggleUserActive('${u.id}',true)">Reactivate</button>`} <button class="btn small alert" onclick="deleteUser('${u.id}')">Remove</button></td></tr>`).join('')}</tbody></table>`}
function toastHtml(){return state.toast?`<div class="toast">${escapeHtml(state.toast)}</div>`:''}function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
init();
